-- Datos de la investigación del 26-10-2026 (generado desde docs/investigacion).
on conflict (item, tienda, consultado_en) do update set precio = excluded.precio, oferta = excluded.oferta, producto = excluded.producto, url = excluded.url;

on conflict (item, gama, consultado_en) do update set precio = excluded.precio, producto = excluded.producto, url = excluded.url;

on conflict (id) do update set nombre = excluded.nombre, categoria = excluded.categoria, dificultad = excluded.dificultad, motor = excluded.motor, prioridad = excluded.prioridad, estado = excluded.estado, datos = excluded.datos, actualizado = now();

on conflict (id) do update set datos = excluded.datos, actualizado = now();
